import './styles.css';
import { useState } from 'react';

interface TimelineEvent {
  year: string;
  title: string;
  description: string;
  impact: 'foundation' | 'breakthrough' | 'milestone' | 'revolution';
  details: string[];
  funFact?: string;
}

const timelineEvents: TimelineEvent[] = [
  {
    year: '1950',
    title: 'The Turing Test',
    description: 'Alan Turing proposes a test for machine intelligence',
    impact: 'foundation',
    details: [
      'Turing asked: "Can machines think?"',
      'Proposed the "imitation game" - could a machine fool a human?',
      'Set the philosophical foundation for AI research',
    ],
    funFact: 'Turing predicted machines would pass his test by 2000 - he was a bit optimistic!',
  },
  {
    year: '1956',
    title: 'AI is Born',
    description: 'The Dartmouth Conference officially launches AI as a field',
    impact: 'foundation',
    details: [
      'John McCarthy coined the term "Artificial Intelligence"',
      'Researchers believed human-level AI was just 20 years away',
      'Marked the beginning of serious AI research funding',
    ],
    funFact: 'The conference proposal claimed AI could be solved in "one summer"!',
  },
  {
    year: '1966',
    title: 'ELIZA',
    description: 'First chatbot creates illusion of understanding',
    impact: 'milestone',
    details: [
      'Created by Joseph Weizenbaum at MIT',
      'Simulated a psychotherapist using pattern matching',
      'People formed emotional connections despite knowing it was a program',
    ],
    funFact: "Weizenbaum's secretary asked him to leave the room so she could chat privately with ELIZA!",
  },
  {
    year: '1980s',
    title: 'AI Winter',
    description: 'Funding and interest in AI collapses',
    impact: 'milestone',
    details: [
      'Early AI failed to deliver on ambitious promises',
      'Government and corporate funding dried up',
      'Research continued but with much less fanfare',
    ],
    funFact: 'Some researchers avoided using the term "AI" to get funding!',
  },
  {
    year: '1997',
    title: 'Deep Blue Beats Kasparov',
    description: 'IBM\'s computer defeats world chess champion',
    impact: 'milestone',
    details: [
      'First time a computer beat a reigning world champion',
      'Used brute-force calculation, not "understanding"',
      'Sparked debates about what machine intelligence really means',
    ],
    funFact: 'Kasparov accused IBM of cheating (they didn\'t).',
  },
  {
    year: '2011',
    title: 'Watson Wins Jeopardy!',
    description: 'IBM\'s Watson beats human champions at trivia',
    impact: 'milestone',
    details: [
      'Had to understand natural language questions',
      'Processed 200 million pages of content',
      'Showed AI could handle ambiguity and wordplay',
    ],
    funFact: 'Watson once answered "Toronto" for a question about U.S. cities!',
  },
  {
    year: '2017',
    title: 'Transformers',
    description: 'Google introduces the architecture behind modern LLMs',
    impact: 'revolution',
    details: [
      'Paper titled "Attention Is All You Need"',
      'Introduced the "attention mechanism" for understanding context',
      'Made it possible to train much larger, more capable models',
    ],
    funFact: 'The paper has been cited over 100,000 times - one of the most influential ever!',
  },
  {
    year: '2018',
    title: 'BERT & GPT',
    description: 'Pre-trained language models change everything',
    impact: 'breakthrough',
    details: [
      'Models could now be trained on general text, then fine-tuned',
      'BERT (Google) improved search dramatically',
      'GPT (OpenAI) showed impressive text generation',
    ],
    funFact: 'BERT improved Google Search results for 10% of all queries!',
  },
  {
    year: '2020',
    title: 'GPT-3',
    description: 'OpenAI\'s massive model stuns the world',
    impact: 'revolution',
    details: [
      '175 billion parameters - 100x larger than GPT-2',
      'Could write essays, code, poetry, and more',
      'Sparked widespread discussion about AI capabilities',
    ],
    funFact: 'Training GPT-3 cost an estimated $4.6 million in compute!',
  },
  {
    year: '2022',
    title: 'ChatGPT Launch',
    description: 'AI goes mainstream with conversational interface',
    impact: 'revolution',
    details: [
      'Reached 100 million users in 2 months (fastest ever)',
      'Made LLMs accessible to everyone',
      'Started global conversation about AI in society',
    ],
    funFact: 'ChatGPT crashed multiple times from overwhelming demand at launch!',
  },
  {
    year: '2023',
    title: 'GPT-4 & Claude',
    description: 'Next-generation models with improved capabilities',
    impact: 'breakthrough',
    details: [
      'Multimodal capabilities (text + images)',
      'Better reasoning and fewer hallucinations',
      'Competition drives rapid improvement',
    ],
    funFact: 'GPT-4 can pass the bar exam in the 90th percentile!',
  },
  {
    year: '2024+',
    title: 'The Present',
    description: 'Rapid advancement continues',
    impact: 'revolution',
    details: [
      'Models like Gemini, Claude 3.5, and GPT-4o',
      'Reasoning models (o1, DeepSeek R1) tackle complex problems',
      'AI becomes integrated into everyday tools',
    ],
    funFact: 'You\'re living through one of the fastest technological shifts in history!',
  },
];

const impactColors = {
  foundation: { bg: '#dbeafe', border: '#3b82f6', text: '#1d4ed8', label: 'Foundation' },
  milestone: { bg: '#fef3c7', border: '#f59e0b', text: '#b45309', label: 'Milestone' },
  breakthrough: { bg: '#d1fae5', border: '#10b981', text: '#047857', label: 'Breakthrough' },
  revolution: { bg: '#fce7f3', border: '#ec4899', text: '#be185d', label: 'Revolution' },
};

function TimelineCard({ event, isSelected, onClick }: {
  event: TimelineEvent;
  isSelected: boolean;
  onClick: () => void;
}) {
  const colors = impactColors[event.impact];

  return (
    <div 
      className={`timeline-card ${isSelected ? 'selected' : ''}`}
      style={{ 
        borderColor: colors.border,
        backgroundColor: isSelected ? colors.bg : 'white'
      }}
      onClick={onClick}
    >
      <div className="card-header">
        <span className="year">{event.year}</span>
        <span 
          className="impact-badge"
          style={{ backgroundColor: colors.bg, color: colors.text }}
        >
          {colors.label}
        </span>
      </div>
      <h3 className="card-title">{event.title}</h3>
      <p className="card-desc">{event.description}</p>
    </div>
  );
}

function DetailPanel({ event }: { event: TimelineEvent }) {
  const colors = impactColors[event.impact];

  return (
    <div className="detail-panel" style={{ borderColor: colors.border }}>
      <div className="detail-header">
        <span className="detail-year">{event.year}</span>
        <h2 className="detail-title">{event.title}</h2>
      </div>

      <div className="detail-content">
        <h4>What Happened</h4>
        <ul className="detail-list">
          {event.details.map((detail, i) => (
            <li key={i}>{detail}</li>
          ))}
        </ul>

        {event.funFact && (
          <div className="fun-fact">
            <span className="fun-fact-label">Fun Fact</span>
            <p>{event.funFact}</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default function App() {
  const [selectedIndex, setSelectedIndex] = useState(0);

  return (
    <div className="app">
      <div className="header">
        <h1>LLM Timeline Explorer</h1>
        <p className="subtitle">
          From Turing's dreams to ChatGPT - explore how we got here
        </p>
      </div>

      <div className="legend">
        {Object.entries(impactColors).map(([key, colors]) => (
          <div key={key} className="legend-item">
            <span 
              className="legend-dot" 
              style={{ backgroundColor: colors.border }}
            />
            <span>{colors.label}</span>
          </div>
        ))}
      </div>

      <div className="main-content">
        <div className="timeline-column">
          <div className="timeline-line" />
          {timelineEvents.map((event, index) => (
            <TimelineCard
              key={event.year}
              event={event}
              isSelected={index === selectedIndex}
              onClick={() => setSelectedIndex(index)}
            />
          ))}
        </div>

        <div className="detail-column">
          <DetailPanel event={timelineEvents[selectedIndex]} />
        </div>
      </div>

      <div className="insight-box">
        <h3>The Big Picture</h3>
        <p>
          Notice how progress wasn't linear! After early optimism in the 1950s, there were "AI winters" where progress stalled. The real breakthroughs came in the 2010s with deep learning, and especially 2017's Transformer architecture.
        </p>
        <p>
          <strong>Key insight:</strong> In just 5 years (2017-2022), we went from specialized AI to chatbots that millions of people use daily. The pace of change is accelerating!
        </p>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #4c1d95 0%, #6d28d9 100%);
  min-height: 100vh;
  padding: 2rem 1rem;
}

.app {
  max-width: 1000px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 2rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.85);
  font-size: 1rem;
}

.legend {
  display: flex;
  justify-content: center;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: white;
  font-size: 0.85rem;
}

.legend-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
}

.main-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
}

@media (max-width: 768px) {
  .main-content {
    grid-template-columns: 1fr;
  }

  .detail-column {
    order: -1;
  }
}

.timeline-column {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  max-height: 600px;
  overflow-y: auto;
  padding-right: 0.5rem;
}

.timeline-line {
  position: absolute;
  left: 20px;
  top: 0;
  bottom: 0;
  width: 3px;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 2px;
}

.timeline-card {
  position: relative;
  background: white;
  border-radius: 0.75rem;
  padding: 1rem;
  padding-left: 3rem;
  border-left: 4px solid;
  cursor: pointer;
  transition: all 0.2s;
  margin-left: 10px;
}

.timeline-card::before {
  content: '';
  position: absolute;
  left: -18px;
  top: 1.25rem;
  width: 12px;
  height: 12px;
  background: white;
  border-radius: 50%;
  border: 3px solid currentColor;
}

.timeline-card:hover {
  transform: translateX(4px);
}

.timeline-card.selected {
  transform: translateX(8px);
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.5rem;
}

.year {
  font-weight: 700;
  color: #1f2937;
  font-size: 0.9rem;
}

.impact-badge {
  font-size: 0.65rem;
  font-weight: 600;
  padding: 0.2rem 0.5rem;
  border-radius: 1rem;
  text-transform: uppercase;
}

.card-title {
  font-size: 1rem;
  color: #1f2937;
  margin-bottom: 0.25rem;
}

.card-desc {
  font-size: 0.8rem;
  color: #6b7280;
  line-height: 1.4;
}

/* Detail Panel */
.detail-column {
  position: sticky;
  top: 2rem;
  height: fit-content;
}

.detail-panel {
  background: white;
  border-radius: 1rem;
  padding: 1.5rem;
  border-top: 4px solid;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.detail-header {
  margin-bottom: 1rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid #e5e7eb;
}

.detail-year {
  display: inline-block;
  font-size: 0.85rem;
  font-weight: 600;
  color: #6b7280;
  background: #f3f4f6;
  padding: 0.25rem 0.75rem;
  border-radius: 1rem;
  margin-bottom: 0.5rem;
}

.detail-title {
  font-size: 1.5rem;
  color: #1f2937;
}

.detail-content h4 {
  font-size: 0.9rem;
  color: #374151;
  margin-bottom: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.detail-list {
  list-style: none;
  margin-bottom: 1.5rem;
}

.detail-list li {
  position: relative;
  padding-left: 1.25rem;
  margin-bottom: 0.5rem;
  color: #4b5563;
  font-size: 0.9rem;
  line-height: 1.5;
}

.detail-list li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0.5rem;
  width: 6px;
  height: 6px;
  background: #8b5cf6;
  border-radius: 50%;
}

.fun-fact {
  background: #fef3c7;
  border-radius: 0.75rem;
  padding: 1rem;
}

.fun-fact-label {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 600;
  color: #b45309;
  background: #fde68a;
  padding: 0.15rem 0.5rem;
  border-radius: 0.25rem;
  margin-bottom: 0.5rem;
  text-transform: uppercase;
}

.fun-fact p {
  color: #92400e;
  font-size: 0.9rem;
  line-height: 1.5;
}

.insight-box {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 1rem;
  padding: 1.5rem;
}

.insight-box h3 {
  color: #1f2937;
  font-size: 1rem;
  margin-bottom: 0.75rem;
}

.insight-box p {
  color: #4b5563;
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 0.75rem;
}

.insight-box p:last-child {
  margin-bottom: 0;
}

/* Scrollbar styling */
.timeline-column::-webkit-scrollbar {
  width: 6px;
}

.timeline-column::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
}

.timeline-column::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.3);
  border-radius: 3px;
}

.timeline-column::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.5);
}
